import {loginPage} from './login.js';import {enablePageSwipe} from './swipe.js';import {readConfig,saveConfig,loadSpots} from './model.js';
const app=document.querySelector('#app'),dialog=document.querySelector('#dialog');let storage;try{storage=localStorage}catch{storage={getItem:()=>null,setItem:()=>{throw Error()}}}let config=readConfig(storage),training=false,loading=false,trainingState={status:'pending',spots:[]};
const nav=[['home','⌂','Início'],['settings','☷','Ajustes'],['spots','♠','Spots'],['store','◇','Loja'],['profile','♙','Perfil']];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const heading=(tag,title,desc)=>`<div class="page-heading"><div><span class="eyebrow">${tag}</span><h1>${title}</h1><p>${desc}</p></div></div>`;
const fields=[['format','Formato',[['tournament','Torneios'],['cash','Cash game']]],['players','Jogadores',['2','6','8','9','10']],['stack','Stack · BB',['20','40','60','100']],['position','Posição',['BTN','CO','HJ','UTG','SB','BB']],['street','Etapa',[['preflop','Pré-flop'],['flop','Flop'],['turn','Turn'],['river','River']]],['duration','Duração · minutos',['5','10','20']]];
const label=(k)=>{const v=fields.find(f=>f[0]===k)?.[2].find(v=>(Array.isArray(v)?v[0]:v)===config[k]);return Array.isArray(v)?v[1]:v||config[k]};
const summary=()=>`<dl class="summary">${fields.map(([k,t])=>`<div><dt>${t}</dt><dd>${label(k)}</dd></div>`).join('')}<div><dt>Modo</dt><dd>${config.level.toUpperCase()}</dd></div></dl>`;
function message(title,body){document.querySelector('#dialog-title').textContent=title;document.querySelector('#dialog-body').textContent=body;dialog.showModal()}dialog.querySelector('.close').onclick=()=>dialog.close();document.querySelector('#dialog-action').onclick=()=>dialog.close();
function render(){const route=location.hash.slice(1)||'login';if(route==='login'){loginPage(app,'GRINDER EVO');return}document.body.classList.remove('login-screen');for(const id of ['navigation','mobile-navigation'])document.getElementById(id).innerHTML=nav.map(([k,s,t])=>`<a href="#${k}" class="${id==='navigation'?'nav-link ':''}${route===k?'active':''}" ${route===k?'aria-current="page"':''}><span class="nav-symbol">${s}</span>${t}</a>`).join('');
if(route==='home')app.innerHTML=heading('SEU PRÓXIMO PASSO NA MESA','Decida. Evolua.<br><em>Domine.</em>','Transforme estudo em prática. Uma decisão de cada vez.')+`<section class="hero grinder-hero"><img class="hero-image" src="assets/pokerinno-grinder.webp" alt="POKERINNO acompanha seu treino"><div class="hero-copy"><span class="eyebrow">POKERINNO · LABORATÓRIO DE TREINO</span><h2>A próxima decisão<br>começa com <em>você.</em></h2><p>Escolha o contexto. Prepare sua sessão. Encontre seu ritmo de evolução.</p><a href="#settings" class="quiet">Configure sua jornada →</a></div></section><div class="section-top"><h2>Escolha seu treino</h2><span>SEU RITMO. SUA EVOLUÇÃO.</span></div><div class="grinder-cards">${[['base','BASE','Fortaleça suas decisões.','settings'],['evo','EVO','Treine novos contextos.','settings'],['advance','ADVANCE','Aprofunde sua prática.','advance']].map(([m,t,d,r],i)=>`<a class="training-card" href="#${r}" data-mode="${m}"><span>0${i+1}</span><h3>${t}</h3><p>${d}</p><b>↗</b></a>`).join('')}</div><div class="coach-note">Uma boa rotina começa com um treino que faz sentido para você.<span>— POKERINNO</span></div>`;
else if(route==='settings'||route==='advance')app.innerHTML=heading('PREPARE SUA SESSÃO',route==='advance'?'Advance.':'Ajustes do treino.','Escolha o contexto das suas próximas decisões.')+`<div class="level-tabs">${['base','evo','advance'].map(v=>`<button data-level="${v}" aria-pressed="${config.level===v}">${v.toUpperCase()}</button>`).join('')}</div><form id="configuration" class="configuration">${fields.map(([k,t,values])=>`<fieldset><legend>${t}</legend><div class="option-grid">${values.map(v=>{const [val,text]=Array.isArray(v)?v:[v,v];return `<label class="choice"><input type="radio" name="${k}" value="${val}" ${config[k]===val?'checked':''}><span>${text}</span></label>`}).join('')}</div></fieldset>`).join('')}</form><a class="primary" href="#spots">Ver treino programado →</a>`;
else if(route==='spots')app.innerHTML=heading('SUA SESSÃO','Spots.','Prepare o treino antes de abrir a mesa.')+(training?table():`<section class="programmed"><div class="section-top"><h2>TREINO PROGRAMADO</h2><span>${config.level.toUpperCase()}</span></div>${summary()}<div class="action-row"><button class="primary" data-start ${loading?'disabled':''}>${loading?'CARREGANDO…':'INICIAR'}</button><a class="quiet" href="#settings">EDITAR</a><button class="quiet" data-cancel>CANCELAR</button></div></section><p class="integration-note">Sua sessão será alimentada pelo motor de spots do app.</p>`);
else if(route==='store')app.innerHTML=heading('SEU TREINO PODE IR ALÉM','Loja.','Escolha os recursos que acompanham sua evolução.')+`<section class="empty"><div class="empty-symbol">◇</div><h2>Seu próximo passo.</h2><p>Os planos e recursos disponíveis aparecerão aqui quando o serviço da loja estiver conectado.</p><button class="quiet" data-info="Loja">Conhecer os recursos →</button></section>`;
else if(route==='profile')app.innerHTML=heading('DO SEU JEITO','Seu perfil.','Conta, preferências e histórico de treino.')+`<section class="profile-intro"><span class="avatar">♠</span><div><h2>Seu jogo tem uma história.</h2><p>Comece seu próximo capítulo.</p></div><a class="primary" href="#login">Acessar conta →</a></section><div class="setting"><div><h3>Formato de jogo</h3><p>${label('format')}</p></div><a href="#settings">Ajustar →</a></div><div class="setting"><div><h3>Histórico de treino</h3><p>Suas sessões reais aparecerão aqui.</p></div><button class="quiet" data-info="Histórico">Consultar →</button></div><div class="setting"><div><h3>Reduzir movimentos</h3><p>Uma experiência com menos animações.</p></div><input id="reduce-motion" type="checkbox" aria-label="Reduzir movimentos" ${document.documentElement.classList.contains('reduced-motion')?'checked':''}></div>`;
else {location.hash='home';return}}
function table(){return `<section class="table-stage"><div class="table-toolbar"><span>${label('format')} · ${config.players} jogadores</span><button class="quiet" data-edit>EDITAR TREINO</button></div><div class="poker-table"><div class="table-center"><span>STACKUP</span><strong>GRINDER EVO</strong><div class="board">${Array.from({length:5},()=>'<span class="card-back">♠</span>').join('')}</div><small>NENHUMA MÃO CARREGADA</small></div>${Array.from({length:Number(config.players)},(_,i)=>{const a=(i/Number(config.players))*Math.PI*2+Math.PI/2;return `<div class="seat" style="left:${50+43*Math.cos(a)}%;top:${50+43*Math.sin(a)}%"><span>${i===0?'VOCÊ':String(i+1).padStart(2,'0')}</span></div>`}).join('')}</div><div class="table-message"><h3>${trainingState.status==='error'?'Não foi possível carregar o treino.':'Sua mesa está preparada.'}</h3><p>${trainingState.status==='ready'&&trainingState.spots.length?'Spots recebidos. A interface de decisão será conectada ao contrato do motor existente.':'O motor de spots ainda precisa ser conectado para iniciar decisões reais.'}</p></div><div class="action-row"><button class="quiet" data-info="Treino">ANTERIOR</button><button class="primary" data-info="Treino">ALL IN</button><button class="quiet" data-info="Treino">PRÓXIMO</button></div><button class="quiet" data-end>Voltar ao treino programado →</button></section>`}
document.addEventListener('change',e=>{if(e.target.closest('#configuration')){config[e.target.name]=e.target.value;saveConfig(storage,config)}if(e.target.id==='reduce-motion')document.documentElement.classList.toggle('reduced-motion',e.target.checked)});
document.addEventListener('click',async e=>{const mode=e.target.closest('[data-mode]'),level=e.target.closest('[data-level]');if(mode){config.level=mode.dataset.mode;saveConfig(storage,config)}if(level){config.level=level.dataset.level;saveConfig(storage,config);render()}if(e.target.closest('[data-start]')){if(loading)return;loading=true;render();trainingState=await loadSpots(window.StackUpGrinderAdapter,config);loading=false;training=true;if(location.hash==='#spots')render()}if(e.target.closest('[data-cancel]')){training=false;location.hash='home'}if(e.target.closest('[data-edit]')){training=false;location.hash='settings'}if(e.target.closest('[data-end]')){training=false;render()}const info=e.target.closest('[data-info]');if(info)message(info.dataset.info,'Este espaço está pronto para receber o serviço do app. Nenhum resultado ou decisão foi simulado.')});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'})});render();enablePageSwipe(nav.map(n=>n[0]));
